SELECT ID, DATE, TIME, TITLE, CLASS_ID
FROM T_SCHEDULE
WHERE KINDERGARTEN_ID = #{kindergartenId}

SELECT ID, KINDERGARTEN_ID, DATE, TIME, TITLE, CLASS_ID, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT, UNIX_TIMESTAMP(UPDATED_AT) * 1000 UPDATED_AT
FROM T_SCHEDULE
WHERE ID = #{id}

mapper.update:
